def solve(data):
    failed = set(data['failed'])
    affected = set()

    def get_successors(node):
        # Находим всех узлов, у которых node является предшественником
        # deps[x] = [p1, p2] означает, что x зависит от p1 и p2
        # Нам нужно найти x, где node в deps[x]
        result = []
        for x, parents in data['deps'].items():
            if node in parents:
                result.append(x)
        return result

    queue = list(failed)
    visited = set(failed)

    while queue:
        current = queue.pop(0)
        if current in visited:
            continue
        visited.add(current)
        for successor in get_successors(current):
            if successor not in visited:
                queue.append(successor)

    return sorted(visited - failed)

